-- StarterGui.SpeedWay.Toggle.LocalScript
local function C_3()
local script = G2L["3"];
	local b = script.Parent
	local frame = b.Parent.MAIN
	local ts = game:GetService("TweenService")
	local ti = TweenInfo.new(0.4, Enum.EasingStyle.Sine, Enum.EasingDirection.In)
	local ti2 = TweenInfo.new(0.25, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut)
	local ticam = TweenInfo.new(0.7, Enum.EasingStyle.Back, Enum.EasingDirection.InOut)
	local camera = workspace.CurrentCamera
	b.Rotation = 180
	local istoggled = false

	b.Activated:Connect(function()
		if not istoggled then
			istoggled = true
			frame.Visible = true
			local t = ts:Create(frame, ti, { GroupTransparency = 0 })
			local tcam = ts:Create(camera, ticam, { FieldOfView = 35 })
			tcam:Play()
			t:Play()
			local t3 = ts:Create(b, ti2, { Rotation = 0 })
			t3:Play()
		else
			local t2 = ts:Create(frame, ti, { GroupTransparency = 1 })
			local tcam2 = ts:Create(camera, ticam, { FieldOfView = 70 })
			tcam2:Play()
			t2:Play()
			t2.Completed:Connect(function()
				frame.Visible = false
				istoggled = false
			end)
			local t4 = ts:Create(b, ti2, { Rotation = 180 })
			t4:Play()
		end
	end)

end;
